-- Month-over-month SLA compliance
-- Tables: tickets, sla_policies
WITH e AS (SELECT strftime('%Y-%m',created_at) month, t.*, p.target_resolution_minutes, CASE WHEN t.resolved_at IS NOT NULL THEN (julianday(t.resolved_at)-julianday(t.created_at))*1440 ELSE (julianday('now')-julianday(t.created_at))*1440 END elapsed FROM tickets t JOIN sla_policies p ON p.policy_id=t.policy_id), m AS (SELECT month, ROUND(100.0*SUM(CASE WHEN resolved_at IS NOT NULL AND elapsed<=target_resolution_minutes THEN 1 ELSE 0 END)/COUNT(*),2) sla_rate FROM e GROUP BY month) SELECT month, sla_rate, LAG(sla_rate) OVER (ORDER BY month) prior_month, ROUND(sla_rate-LAG(sla_rate) OVER (ORDER BY month),2) AS change_pct_points FROM m ORDER BY month;
